const uint8_t LED_PIN = 4;                 // J1 pin 4, through 330 Ω
const uint8_t RGB_PIN = {{p:rgbPin}};                // RGB LED data: 38 on v1.1, 48 on v1.0
const unsigned long HALF_MS = {{p:halfMs}};

void setup() {
  Serial.begin(115200);
  pinMode(LED_PIN, OUTPUT);
  Serial.println("blink ready");
}

