// Blink an LED on GPIO4 and the RGB LED
const uint8_t LED_PIN = 4;                 // J1 pin 4, through 330 Ω
const uint8_t RGB_PIN = 38;                // RGB LED data: 38 on v1.1, 48 on v1.0
const unsigned long HALF_MS = 500;

void setup() {
  Serial.begin(115200);
  pinMode(LED_PIN, OUTPUT);
  Serial.println("blink ready");
}

void loop() {
  digitalWrite(LED_PIN, HIGH);
  rgbLedWrite(RGB_PIN, 64, 0, 0);          // red at 64 of 255
  Serial.println("on");
  delay(HALF_MS);
  digitalWrite(LED_PIN, LOW);
  rgbLedWrite(RGB_PIN, 0, 0, 0);           // all three colours off
  Serial.println("off");
  delay(HALF_MS);
}
